const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/clearcache";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "package.json"), JSON.stringify({ name: "cc", type: "module" }));
fs.writeFileSync(path.join(dir, "check.mjs"), [
  "import { createVitest } from '/w/node_modules/vitest/dist/node.js'",
  "const v = await createVitest('test', { watch: false, root: " + JSON.stringify(dir) + ", config: false })",
  "const r = { clearCache: typeof v.clearCache, old: typeof v.experimental_clearCache }",
  "if (typeof v.clearCache === 'function') {",
  "  try { await v.clearCache(); r.called = 'ok' } catch (e) { r.called = 'threw: ' + e.message }",
  "}",
  "await v.close()",
  "console.log('RESULT ' + JSON.stringify(r))",
  "process.exit(0)",
].join("\n") + "\n");
const p = cp.spawnSync(process.execPath, [path.join(dir, "check.mjs")], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (p.stdout || "") + (p.stderr || "") + (p.error ? String(p.error) : "");
console.log(out);
const m = out.match(/RESULT (\{.*\})/);
if (!m) {
  console.error("ERROR: createVitest check did not finish (exit " + p.status + ")");
  process.exit(2);
}
const r = JSON.parse(m[1]);
if (r.clearCache === "function" && r.called === "ok") {
  console.log("PASS: vitest.clearCache() resolved");
  process.exit(0);
}
if (r.clearCache === "undefined" && r.old === "function") {
  console.error("FAIL: vitest.clearCache is undefined, only experimental_clearCache exists");
  process.exit(1);
}
console.error("ERROR: unexpected result " + m[1]);
process.exit(2);

